from pathlib import Path
import json
import os

ROOT=Path(__file__).resolve().parents[2]
PROGRAM=(ROOT/'docs/BOS/PROGRAMA_ESTRATEGICO_BOS_EDARSAHUB_DIRECCION.md').read_text(encoding='utf-8').lower()

def corpus():
    parts=[]
    for base in (ROOT/'backend', ROOT/'docs'):
        for p in base.rglob('*'):
            if p.is_file() and p.suffix.lower() in {'.py','.md','.json'} and 'test_bos_v1_gate_c_functional_coverage_certification.py' not in str(p):
                try: parts.append(p.read_text(encoding='utf-8',errors='ignore').lower())
                except Exception: pass
    return '\n'.join(parts)

def certified_job_ids():
    runtime=Path(str(os.environ.get('EDARSAHUB_ROOT') or '/app'))/'.git/universal-worker-queue/results'
    ids=[]
    if runtime.is_dir():
        for p in runtime.glob('*.json'):
            try:
                d=json.loads(p.read_text(encoding='utf-8'))
                if d.get('certification') in {'CERTIFIED','CERTIFIED_READ_ONLY'} and d.get('percent_complete')==100 and not d.get('production_touched',False): ids.append(str(d.get('job_id','')).lower())
            except Exception: pass
    return ids

def test_gate_c_existing_coverage_is_complete():
    assert 'gate c - cobertura funcional' in PROGRAM
    text=corpus(); jobs='\n'.join(certified_job_ids())
    groups={
      'comercial':['comercial','ventas'],
      'costos_margenes':['costos','margen'],
      'finanzas_tesoreria':['finanzas','tesoreria','cxp','pago'],
      'inventarios':['inventario','almacen'],
      'clientes_crm':['cliente','crm'],
      'operaciones':['operacion','operaciones'],
      'administracion':['administracion','admin']
    }
    missing=[]
    for name,tokens in groups.items():
        repository_ok=any(t in text for t in tokens)
        terminal_ok=any(any(t in jid for t in tokens) for jid in jobs)
        if not (repository_ok and terminal_ok): missing.append(name)
    assert not missing, 'GATE_C_MISSING_EVIDENCE:'+','.join(missing)
